SELECT b.ENDDATE AS `交易日期`, b.STOCKSNAME AS `股票名称`, b.STOCKCODE AS `股票代码`, ROUND(b.TCLOSE, 2) AS `收盘价(元)`, ROUND(b.TOPEN, 2) AS `开盘价(元)`, ROUND(b.THIGH, 2) AS `最高价(元)`, ROUND(b.TLOW, 2) AS `最低价(元)`, ROUND(b.TVOLUME/1000000, 2) AS `成交量(百万股)`, ROUND(b.TVALUE/100000000, 2) AS `成交额(亿元)`, ROUND(b.MKTCAP/100000000, 1) AS `流通市值(亿元)`, ROUND(b.TCAP/100000000, 1) AS `总市值(亿元)` FROM GET_A_SEC_CODE a JOIN ANA_STK_EXPR_IDX b ON a.INNER_CODE = b.INNER_CODE WHERE a.SEC_SNAME LIKE '%中国平安%' AND b.ENDDATE >= '2026-08-01 00:00:00.000' AND b.ENDDATE <= '2026-08-31 23:59:59.999' AND a.ISVALID = 1 AND b.TCLOSE IS NOT NULL ORDER BY b.TCLOSE ASC LIMIT 1;
